/**
 * LIA → Nim emitter.
 */
import { parseLia } from './compiler.mjs';
import { parseParamList, safeEmitId, isJsRuntimeOnly } from './emit_shared.mjs';

export function emitNim(liaText, opts = {}) {
  const prog = parseLia(liaText);
  const parts = [
    '# generated by lia multi-emit → nim',
    'import strutils',
    '',
    'proc _lia_typeof*(x: auto): string = "object"',
    'proc _lia_num*(x: auto): int64 = 0',
    '',
  ];

  for (const fn of prog.fns) {
    const { names: params } = parseParamList(fn.params);
    const nimName = safeEmitId(fn.name);
    if (opts.stubRuntime !== false || isJsRuntimeOnly(fn.body, fn.name)) {
      parts.push(`proc ${nimName}*() = discard`);
      continue;
    }
    const paramList = params.map((p) => `${safeEmitId(p)}: auto`).join(', ');
    parts.push(`proc ${nimName}*(${paramList}) =`);
    parts.push('  discard');
  }

  return { code: parts.join('\n'), lang: 'nim' };
}
